// TypeScript config parser module

interface DatabaseConfig {
  url: string
  maxConnections: number
}

type LogLevel = 'debug' | 'info' | 'warn' | 'error'

interface Config {
  port: number
  host: string
  logLevel: LogLevel
  database: DatabaseConfig
}

const VALID_LOG_LEVELS: LogLevel[] = ['debug', 'info', 'warn', 'error']

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

export function parseConfig(raw: unknown): Config {
  if !isObject(raw): throw new Error('Config must be an object')

  // Validate port
  if typeof raw.port !== 'number' || !Number.isInteger(raw.port) || raw.port < 0 || raw.port > 65535:
    throw new Error('port must be an integer between 0 and 65535')

  // Validate host
  if typeof raw.host !== 'string' || raw.host.trim() === '':
    throw new Error('host must be a non-empty string')

  // Validate logLevel
  if !VALID_LOG_LEVELS.includes(raw.logLevel as LogLevel):
    throw new Error(`logLevel must be one of: ${VALID_LOG_LEVELS.join(', ')}`)

  // Validate database
  if !isObject(raw.database):
    throw new Error('database must be an object')
  if typeof raw.database.url !== 'string' || raw.database.url.trim() === '':
    throw new Error('database.url must be a non-empty string')
  if typeof raw.database.maxConnections !== 'number' || !Number.isInteger(raw.database.maxConnections) || raw.database.maxConnections < 1:
    throw new Error('database.maxConnections must be a positive integer')

  return {
    port: raw.port as number,
    host: raw.host as string,
    logLevel: raw.logLevel as LogLevel,
    database: {
      url: raw.database.url as string,
      maxConnections: raw.database.maxConnections as number,
    },
  }
}

export function loadConfigFromEnv(): Config {
  const raw: Record<string, unknown> = {
    port: process.env.PORT ? parseInt(process.env.PORT, 10) : 3000,
    host: process.env.HOST || 'localhost',
    logLevel: process.env.LOG_LEVEL || 'info',
    database: {
      url: process.env.DATABASE_URL || 'postgresql://localhost:5432/app',
      maxConnections: process.env.DB_MAX_CONNECTIONS ? parseInt(process.env.DB_MAX_CONNECTIONS, 10) : 10,
    },
  }
  return parseConfig(raw)
}
